// astro.config.mjs — AID docs site configuration
//
// Sidebar contract:
//   - Get Started: autogenerate (order and label come from each page's frontmatter).
//   - Guides, Concepts, Reference, Contact Us: explicit slug items.
//   - Skills: All skills, then an autogenerated collapsed subgroup.
//   - Releases: slug item (releases/changelog, a docs page).

import { readFileSync } from 'node:fs';
import { defineConfig } from 'astro/config';
import starlight from '@astrojs/starlight';
import sitemap from '@astrojs/sitemap';

const AID_VERSION = readFileSync(new URL('../VERSION', import.meta.url), 'utf8').trim().replace(/^v/, '');
if (!/^\d+\.\d+\.\d+/.test(AID_VERSION)) throw new Error('astro.config.mjs: ../VERSION is not a version: ' + AID_VERSION);

export default defineConfig({
  vite: { define: { __AID_VERSION__: JSON.stringify(AID_VERSION) } },

  // Canonical site address and base path.
  site: 'https://aid.casuloailabs.com',
  base: '/',

  // Astro's link prefetch ships a script on every page and has none of the purposes AC-15 allows.
  prefetch: false,

  redirects: {
    '/get-started': '/get-started/overview/',
    '/concepts': '/concepts/methodology/',
    '/concepts/overview': '/concepts/methodology/',
    '/reference': '/reference/overview/',
    '/reference/skills': '/skills/',
  },

  // Without this, pipe tables in .mdx pages render as raw text (Starlight's MDX integration
  // does not turn GitHub-flavoured tables on by itself). Tables in .md pages work either way.
  markdown: { gfm: true },

  integrations: [
    starlight({
      title: 'AID — AI Integrated Development',

      social: [{ icon: 'github', label: 'GitHub', href: 'https://github.com/AndreVianna/aid-methodology' }],
      expressiveCode: { frames: { showCopyToClipboardButton: false } },

      customCss: ['./src/styles/tokens.css', './src/styles/site.css'],

      favicon: '/favicon.svg',

      tableOfContents: { minHeadingLevel: 2, maxHeadingLevel: 3 },

      defaultLocale: 'en',

      sidebar: [
        { label: 'Home', slug: '' },
        { label: 'Get Started', items: [{ autogenerate: { directory: 'get-started' } }] },
        {
          label: 'Guides',
          items: [
            { label: 'Installation', slug: 'guides/installation' },
            { label: 'Working the pipeline', slug: 'guides/pipeline' },
            { label: 'Web dashboard', slug: 'guides/dashboard' },
            { label: 'Maintainer', slug: 'guides/maintainer' },
          ],
        },
        {
          label: 'Concepts',
          items: [
            { label: 'The methodology', slug: 'concepts/methodology' },
            { label: 'The pipeline', slug: 'concepts/pipeline' },
            { label: 'Knowledge Base', slug: 'concepts/knowledge-base' },
            { label: 'Agents', slug: 'concepts/agents' },
            { label: 'Feedback loops', slug: 'concepts/feedback-loops' },
            { label: 'Case studies', slug: 'concepts/case-studies' },
            { label: 'AID and spec-driven development', slug: 'concepts/aid-and-sdd' },
            { label: 'FAQ', slug: 'concepts/faq' },
          ],
        },
        {
          label: 'Reference',
          items: [
            { label: 'Overview', slug: 'reference/overview' },
            { label: 'CLI commands', slug: 'reference/cli' },
            { label: 'Agents', slug: 'reference/agents' },
            { label: 'Knowledge Base documents', slug: 'reference/kb' },
            { label: 'Settings keys', slug: 'reference/settings' },
            { label: 'Artifacts', slug: 'reference/artifacts' },
            { label: 'Repository structure', slug: 'reference/repository-structure' },
            { label: 'Glossary', slug: 'reference/glossary' },
          ],
        },
        // Skills group: explicit index item first,
        // then an autogenerated collapsed subgroup for the skill pages. The
        // page count is deliberately not restated: `autogenerate` enumerates whatever
        // `src/content/docs/skills/` holds, which is the only authority for it, and
        // this config is correct at any roster size.
        {
          label: 'Skills',
          items: [
            { label: 'All skills', slug: 'skills' },
            {
              label: 'Every skill',
              collapsed: true,
              items: [{ autogenerate: { directory: 'skills' } }],
            },
          ],
        },
        {
          label: 'Releases',
          items: [
            { label: 'Changelog', slug: 'releases/changelog' },
          ],
        },
        {
          label: 'Contact Us',
          items: [
            { label: 'Report a site problem', slug: 'contact/site-issue' },
            { label: 'Report an AID bug', slug: 'contact/methodology-bug' },
            { label: 'Ask or give feedback', slug: 'contact/feedback' },
            { label: 'Request a conversation', slug: 'contact/contact-request' },
          ],
        },
      ],

      // Component override map.
      components: {
        // One-row header. See src/components/overrides/.
        Header: './src/components/overrides/Header.astro',
        // Single-language site: nothing to select, and the picker's script goes with it.
        LanguageSelect: './src/components/overrides/LanguageSelect.astro',
        Footer: './src/components/Footer.astro',
      },

      // Pagefind (built-in) powers the search box; no extra config needed.
      // It builds a static index at astro build time — no external SaaS request.
    }),

    // @astrojs/sitemap emits sitemap-index.xml + sitemap-0.xml into dist/
    sitemap(),
  ],
});
